const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

/* ------------------------------------------------------------------ */
/*  Capture element references before an action                        */
/* ------------------------------------------------------------------ */

When('I capture the list item element for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      this.capturedElement = items[i];
      return;
    }
  }
  assert.fail(`Todo "${title}" not found for capture`);
});

When('I capture all list item elements', function () {
  this.capturedElements = Array.from(this.document.querySelectorAll('.todo-list li'));
  assert.ok(this.capturedElements.length > 0, 'No list items to capture');
});

/* ------------------------------------------------------------------ */
/*  DOM connectivity assertions                                        */
/* ------------------------------------------------------------------ */

Then('the captured list item element is still connected to the DOM', function () {
  assert.ok(this.capturedElement, 'No captured element to check');
  assert.ok(this.capturedElement.isConnected,
    'Captured element is detached from the DOM — the list was re-rendered');
});

Then('the captured list item element is not connected to the DOM', function () {
  assert.ok(this.capturedElement, 'No captured element to check');
  assert.ok(!this.capturedElement.isConnected,
    'Captured element is still connected to the DOM');
});

Then('every captured list item element is still connected to the DOM', function () {
  assert.ok(this.capturedElements, 'No captured elements to check');
  assert.ok(this.capturedElements.length > 0, 'Captured elements array is empty');
  const detached = this.capturedElements.filter(function (el) { return !el.isConnected; });
  assert.strictEqual(detached.length, 0,
    detached.length + ' captured element(s) are detached from the DOM — the list was re-rendered');
});

/* ------------------------------------------------------------------ */
/*  Class assertions on captured elements                              */
/* ------------------------------------------------------------------ */

Then('the captured list item element has class {string}', function (className) {
  assert.ok(this.capturedElement, 'No captured element to check');
  assert.ok(this.capturedElement.classList.contains(className),
    'Captured element does not have class "' + className + '"');
});

Then('the captured list item element does not have class {string}', function (className) {
  assert.ok(this.capturedElement, 'No captured element to check');
  assert.ok(!this.capturedElement.classList.contains(className),
    'Captured element unexpectedly has class "' + className + '"');
});

Then('every captured list item element has class {string}', function (className) {
  assert.ok(this.capturedElements, 'No captured elements to check');
  const missing = this.capturedElements.filter(function (el) { return !el.classList.contains(className); });
  assert.strictEqual(missing.length, 0,
    missing.length + ' captured element(s) do not have class "' + className + '"');
});

Then('no captured list item element has class {string}', function (className) {
  assert.ok(this.capturedElements, 'No captured elements to check');
  const found = this.capturedElements.filter(function (el) { return el.classList.contains(className); });
  assert.strictEqual(found.length, 0,
    found.length + ' captured element(s) unexpectedly have class "' + className + '"');
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

/* ------------------------------------------------------------------ */
/*  Background / app load                                              */
/* ------------------------------------------------------------------ */

Given('the app is loaded', function () {
  // The Before hook in world.js already loads the app before every scenario.
  // This step is a no-op that anchors the Given clause.
});

/* ------------------------------------------------------------------ */
/*  New-todo input                                                     */
/* ------------------------------------------------------------------ */

When('I type {string} into the new-todo input and press Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
  input.value = text;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

/* ------------------------------------------------------------------ */
/*  Todo list assertions                                               */
/* ------------------------------------------------------------------ */

Then('the todo list is empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'Expected todo list to be empty');
});

Then('the todo list contains {int} item', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, `Expected ${count} items, found ${items.length}`);
});

Then('the todo list contains {int} items', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, `Expected ${count} items, found ${items.length}`);
});

Then('the new item has title {string}', function (expectedTitle) {
  const items = this.document.querySelectorAll('.todo-list li');
  const lastItem = items[items.length - 1];
  assert.ok(lastItem, 'No todo items found');
  const label = lastItem.querySelector('label');
  assert.ok(label, 'Last todo item has no label');
  assert.strictEqual(label.textContent.trim(), expectedTitle,
    `Expected title "${expectedTitle}", got "${label.textContent.trim()}"`);
});

Then('the new item is not completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  const lastItem = items[items.length - 1];
  assert.ok(lastItem, 'No todo items found');
  assert.ok(!lastItem.classList.contains('completed'), 'Expected new item to not be completed');
});

Then('the new-todo input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
  assert.strictEqual(input.value, '', 'Expected new-todo input to be cleared');
});

/* ------------------------------------------------------------------ */
/*  Section visibility                                                 */
/* ------------------------------------------------------------------ */

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  assert.ok(main, 'Main section not found');
  // happy-dom does not implement getComputedStyle, so check inline style / hidden attribute
  assert.ok(main.style.display === 'none' || main.hidden || main.classList.contains('hidden'),
    'Expected main section to be hidden');
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  assert.ok(main, 'Main section not found');
  assert.ok(main.style.display !== 'none' && !main.hidden && !main.classList.contains('hidden'),
    'Expected main section to be visible');
});

Then('the footer is hidden', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer, 'Footer not found');
  assert.ok(footer.style.display === 'none' || footer.hidden || footer.classList.contains('hidden'),
    'Expected footer to be hidden');
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer, 'Footer not found');
  assert.ok(footer.style.display !== 'none' && !footer.hidden && !footer.classList.contains('hidden'),
    'Expected footer to be visible');
});

/* ------------------------------------------------------------------ */
/*  Todo-count                                                         */
/* ------------------------------------------------------------------ */

Then('the todo-count reads {string}', function (expected) {
  const el = this.document.querySelector('.todo-count');
  assert.ok(el, 'todo-count element not found');
  assert.strictEqual(el.textContent.trim(), expected,
    `Expected todo-count "${expected}", got "${el.textContent.trim()}"`);
});

/* ------------------------------------------------------------------ */
/*  Todos with pre-populated state                                     */
/* ------------------------------------------------------------------ */

Given('the app is loaded with todos:', function (dataTable) {
  // The Before hook already loaded the app. Now populate todos from the table.
  const rows = dataTable.hashes();
  for (let i = 0; i < rows.length; i++) {
    const input = this.document.querySelector('.new-todo');
    input.value = rows[i].title;
    input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
      key: 'Enter', keyCode: 13, bubbles: true
    }));
  }
  // Mark completed todos as specified in the table
  for (let i = 0; i < rows.length; i++) {
    if (rows[i].completed === 'true') {
      const items = this.document.querySelectorAll('.todo-list li');
      const toggle = items[i].querySelector('.toggle');
      if (toggle && !toggle.checked) {
        toggle.click();
      }
    }
  }
});

/* ------------------------------------------------------------------ */
/*  Toggle completion                                                  */
/* ------------------------------------------------------------------ */

When('I toggle the {string} todo', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      const toggle = items[i].querySelector('.toggle');
      assert.ok(toggle, `Toggle for "${title}" not found`);
      toggle.click();
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});

/* ------------------------------------------------------------------ */
/*  Completion assertions                                              */
/* ------------------------------------------------------------------ */

Then('the {string} todo is marked completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      assert.ok(items[i].classList.contains('completed'),
        `Expected "${title}" to be completed`);
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});

Then('the {string} todo is not completed', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      assert.ok(!items[i].classList.contains('completed'),
        `Expected "${title}" to not be completed`);
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});
/* ------------------------------------------------------------------ */
/*  Mark all as complete                                               */
/* ------------------------------------------------------------------ */

When('I toggle the mark-all-complete checkbox', function () {
  const checkbox = this.document.querySelector('.toggle-all');
  assert.ok(checkbox, 'toggle-all checkbox not found');
  checkbox.click();
});

Then('every todo is marked completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    assert.ok(items[i].classList.contains('completed'),
      `Expected todo ${i} to be completed`);
  }
});

Then('the mark-all-complete checkbox is checked', function () {
  const checkbox = this.document.querySelector('.toggle-all');
  assert.ok(checkbox, 'toggle-all checkbox not found');
  assert.ok(checkbox.checked, 'Expected toggle-all checkbox to be checked');
});

Then('the mark-all-complete checkbox is not checked', function () {
  const checkbox = this.document.querySelector('.toggle-all');
  assert.ok(checkbox, 'toggle-all checkbox not found');
  assert.ok(!checkbox.checked, 'Expected toggle-all checkbox to not be checked');
});

/* ------------------------------------------------------------------ */
/*  Clear completed                                                    */
/* ------------------------------------------------------------------ */

When('I click the clear-completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.ok(btn, 'clear-completed button not found');
  btn.click();
});

/* ------------------------------------------------------------------ */
/*  Destroy / hover                                                    */
/* ------------------------------------------------------------------ */

When('I hover over the {string} todo', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      items[i].dispatchEvent(new this.window.Event('mouseover', { bubbles: true }));
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});

Then('the destroy button for {string} is visible', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      const btn = items[i].querySelector('.destroy');
      assert.ok(btn, `Destroy button for "${title}" not found`);
      assert.ok(btn.style.display !== 'none' && !btn.hidden,
        `Destroy button for "${title}" is not visible`);
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});

When('I click the destroy button for {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      const btn = items[i].querySelector('.destroy');
      assert.ok(btn, `Destroy button for "${title}" not found`);
      btn.click();
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});

Then('the todo list does not contain {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      assert.fail(`Todo "${title}" should not be in the list`);
    }
  }
});

/* ------------------------------------------------------------------ */
/*  Editing mode                                                       */
/* ------------------------------------------------------------------ */

When('I double-click the label of {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});

Then('the {string} todo is in editing mode', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      assert.ok(items[i].classList.contains('editing'),
        `Expected "${title}" todo to be in editing mode`);
      return;
    }
  }
  assert.fail(`Todo "${title}" not found`);
});

Then('the edit input is focused', function () {
  const active = this.document.activeElement;
  assert.ok(active && active.classList.contains('edit'),
    'Expected edit input to be focused');
});

Then('the edit input value is {string}', function (expected) {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(edit, 'Edit input not found');
  assert.strictEqual(edit.value, expected,
    `Expected edit value "${expected}", got "${edit.value}"`);
});

Then('the toggle checkbox is hidden', function () {
  const toggle = this.document.querySelector('.todo-list li.editing .toggle');
  assert.ok(toggle, 'Toggle checkbox not found');
  const view = toggle.closest('.view');
  // The toggle may be hidden by parent .view being display:none
  assert.ok(toggle.style.display === 'none' || toggle.hidden || toggle.classList.contains('hidden') ||
    (view && (view.style.display === 'none' || view.hidden)),
    'Expected toggle checkbox to be hidden');
});

Then('the destroy button is hidden', function () {
  const btn = this.document.querySelector('.todo-list li.editing .destroy');
  assert.ok(btn, 'Destroy button not found');
  const view = btn.closest('.view');
  assert.ok(btn.style.display === 'none' || btn.hidden || btn.classList.contains('hidden') ||
    (view && (view.style.display === 'none' || view.hidden)),
    'Expected destroy button to be hidden');
});

/* ------------------------------------------------------------------ */
/*  Edit input operations                                              */
/* ------------------------------------------------------------------ */

When('I type {string} into the edit input and press Enter', function (text) {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(edit, 'Edit input not found');
  edit.value = text;
  edit.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, bubbles: true
  }));
});

When('I type {string} into the edit input and blur', function (text) {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(edit, 'Edit input not found');
  edit.value = text;
  edit.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  edit.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('I type {string} into the edit input and press Escape', function (text) {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(edit, 'Edit input not found');
  edit.value = text;
  edit.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Escape', keyCode: 27, bubbles: true
  }));
});

/* ------------------------------------------------------------------ */
/*  Editing mode assertions                                            */
/* ------------------------------------------------------------------ */

Then('the {string} todo is not in editing mode', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      assert.ok(!items[i].classList.contains('editing'),
        `Expected "${title}" todo to not be in editing mode`);
      return;
    }
  }
  // Todo not found by old title — it was renamed, which means editing ended. Pass.
});

Then('the {string} todo exists', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      return; // found
    }
  }
  assert.fail(`Todo "${title}" not found`);
});

Then('the {string} todo does not exist', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      assert.fail(`Todo "${title}" should not exist`);
    }
  }
});

Then('the todo item title is {string}', function (expected) {
  const items = this.document.querySelectorAll('.todo-list li');
  const label = items[0].querySelector('label');
  assert.ok(label, 'No todo label found');
  assert.strictEqual(label.textContent.trim(), expected,
    `Expected title "${expected}", got "${label.textContent.trim()}"`);
});

/* ------------------------------------------------------------------ */
/*  Counter checks                                                     */
/* ------------------------------------------------------------------ */

When('I check the todo-count', function () {
  // No-op: the subsequent Then steps will read the count
});

When('I check the todo-count element', function () {
  // No-op: the subsequent Then step reads the element
});

When('I create a todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
  input.value = title;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, bubbles: true
  }));
});

Then('it reads {string}', function (expected) {
  const el = this.document.querySelector('.todo-count');
  assert.ok(el, 'todo-count element not found');
  assert.strictEqual(el.textContent.trim(), expected,
    `Expected todo-count text "${expected}", got "${el.textContent.trim()}"`);
});

Then('the count number is wrapped in a <strong> tag', function () {
  const strong = this.document.querySelector('.todo-count strong');
  assert.ok(strong, 'Expected a <strong> tag inside .todo-count');
  const num = parseInt(strong.textContent, 10);
  assert.ok(!isNaN(num), `Expected strong content to be a number, got "${strong.textContent}"`);
});

/* ------------------------------------------------------------------ */
/*  Todo list contains specific item                                   */
/* ------------------------------------------------------------------ */

Then('the todo list contains {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('label');
    if (label && label.textContent.trim() === title) {
      return; // found
    }
  }
  assert.fail(`Expected todo list to contain "${title}"`);
});

Then('the clear-completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.ok(btn, 'clear-completed button not found');
  assert.ok(btn.style.display === 'none' || btn.hidden || btn.classList.contains('hidden'),
    'Expected clear-completed button to be hidden');
});

Then('the clear-completed button is visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.ok(btn, 'clear-completed button not found');
  assert.ok(btn.style.display !== 'none' && !btn.hidden && !btn.classList.contains('hidden'),
    'Expected clear-completed button to be visible');
});

/* ------------------------------------------------------------------ */
/*  Persistence / reload                                               */
/* ------------------------------------------------------------------ */

When('I reload the app', function () {
  var fs = require('node:fs');
  var path = require('node:path');
  var ROOT = path.resolve(__dirname, '..', '..');

  // Save the persisted data before destroying the current window
  var savedData = null;
  var savedFilter = null;
  if (this.window && this.window.localStorage) {
    savedData = this.window.localStorage.getItem('todos-javascript');
    savedFilter = this.window.localStorage.getItem('todos-javascript_filter');
  }

  // Build a fresh window with the same page but inject saved data before app.js runs
  var Window = require('happy-dom').Window;
  var w = new Window({
    url: 'http://localhost/',
    settings: { disableJavaScriptFileLoading: true },
  });
  if (savedData !== null) {
    w.localStorage.setItem('todos-javascript', savedData);
  }
  if (savedFilter !== null) {
    w.localStorage.setItem('todos-javascript_filter', savedFilter);
  }
  var d = w.document;
  d.write(fs.readFileSync(path.join(ROOT, 'index.html'), 'utf8'));
  d.close();
  var appSource = fs.readFileSync(path.join(ROOT, 'js', 'app.js'), 'utf8');
  w.eval(appSource);
  d.dispatchEvent(new w.Event('DOMContentLoaded', { bubbles: true }));
  w.dispatchEvent(new w.Event('load'));

  // Routing shim (same as world.js)
  d.addEventListener('click', function (e) {
    var a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
    if (!a) return;
    var next = a.getAttribute('href');
    if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
  }, true);

  // Dispose old window and replace
  if (this.window && typeof this.window.happyDOM && typeof this.window.happyDOM.close === 'function') {
    this.window.happyDOM.close();
  }
  this.window = w;
  this.document = d;
});

Then('the localStorage key {string} contains the todo data', function (key) {
  const data = this.window.localStorage.getItem(key);
  assert.ok(data, `Expected localStorage key "${key}" to contain data`);
  const parsed = JSON.parse(data);
  assert.ok(Array.isArray(parsed), 'Expected localStorage data to be an array');
  assert.ok(parsed.length > 0, 'Expected localStorage data to have at least one item');
});

Then('each stored item has keys {string}, {string}, and {string}', function (key1, key2, key3) {
  const data = this.window.localStorage.getItem('todos-javascript');
  assert.ok(data, 'Expected todos-javascript in localStorage');
  const parsed = JSON.parse(data);
  assert.ok(Array.isArray(parsed), 'Expected array in localStorage');
  for (let i = 0; i < parsed.length; i++) {
    const item = parsed[i];
    assert.ok(item.hasOwnProperty(key1), `Item ${i} missing key "${key1}"`);
    assert.ok(item.hasOwnProperty(key2), `Item ${i} missing key "${key2}"`);
    assert.ok(item.hasOwnProperty(key3), `Item ${i} missing key "${key3}"`);
  }
});

Then('no todo is in editing mode', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    assert.ok(!items[i].classList.contains('editing'),
      `Expected no todo to be in editing mode, but todo ${i} is editing`);
  }
});

