const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..', '..');

Given('the project root', function () {
  this.projectRoot = ROOT;
});

When('I list the project root files', function () {
  this.rootFiles = fs.readdirSync(this.projectRoot || ROOT);
});

Then('the file {string} exists at the project root', function (filename) {
  const filePath = path.join(this.projectRoot || ROOT, filename);
  assert.ok(fs.existsSync(filePath), `Expected ${filename} to exist at ${filePath}`);
  this.currentFile = filename;
  this.currentContent = fs.readFileSync(filePath, 'utf8');
});

Then('{string} contains a script element with src {string}', function (filename, src) {
  const content = this.currentContent || fs.readFileSync(
    path.join(this.projectRoot || ROOT, filename), 'utf8'
  );
  // Parse script tags from the HTML content
  const scriptRegex = new RegExp('<script[^>]*src\\s*=\\s*"([^"]*)"[^>]*>', 'gi');
  let match;
  let found = false;
  while ((match = scriptRegex.exec(content)) !== null) {
    if (match[1] === src) {
      found = true;
      break;
    }
  }
  assert.ok(found, `Expected ${filename} to contain a script element with src "${src}"`);
});

Then('{string} contains the new-todo input element', function (filename) {
  const content = this.currentContent || fs.readFileSync(
    path.join(this.projectRoot || ROOT, filename), 'utf8'
  );
  // Check for input with class "new-todo"
  assert.ok(
    /<input[^>]*class\s*=\s*"new-todo"[^>]*>/.test(content),
    `Expected ${filename} to contain the new-todo input element`
  );
});

Then('{string} contains a section with class {string}', function (filename, className) {
